use serde::Serialize;

#[derive(Clone, Copy)]
pub struct Point { pub x: [f64; 4], pub y: f64 }
#[derive(Serialize)]
pub struct Linear { pub kind: &'static str, pub feature: usize, pub slope: f64, pub intercept: f64 }
#[derive(Serialize)]
pub struct Tree { value: f64, #[serde(skip_serializing_if = "Option::is_none")] feature: Option<usize>, #[serde(skip_serializing_if = "Option::is_none")] threshold: Option<f64>, #[serde(skip_serializing_if = "Option::is_none")] left: Option<Box<Tree>>, #[serde(skip_serializing_if = "Option::is_none")] right: Option<Box<Tree>> }
#[derive(Serialize)]
pub struct Forest { pub kind: &'static str, pub trees: Vec<Tree>, #[serde(rename = "featureCount")] pub feature_count: usize }
#[derive(Serialize)]
pub struct Metrics { pub mae: f64, pub rmse: f64, pub r2: f64, pub train_rows: usize, pub test_rows: usize }
pub struct Models { pub linear: Linear, pub forest: Forest, pub linear_metrics: Metrics, pub forest_metrics: Metrics, pub test: Vec<Point> }
fn mean(rows: &[Point]) -> f64 { rows.iter().map(|p|p.y).sum::<f64>() / rows.len().max(1) as f64 }
pub fn dataset() -> Vec<Point> { include_str!("../data/demand-sales-1200.csv").lines().skip(1).filter_map(|l| { let c: Vec<_> = l.trim().split(',').collect(); if c.len()<9 {return None} Some(Point{x:[c[3].parse().ok()?,c[4].parse().ok()?,c[5].parse().ok()?,c[6].parse().ok()?],y:c[7].parse().ok()?}) }).collect() }
fn fit_linear(rows: &[Point]) -> Linear { let mx=rows.iter().map(|p|p.x[3]).sum::<f64>()/rows.len() as f64; let my=mean(rows); let den=rows.iter().map(|p|(p.x[3]-mx).powi(2)).sum::<f64>(); let slope=if den==0.0 {0.0} else {rows.iter().map(|p|(p.x[3]-mx)*(p.y-my)).sum::<f64>()/den}; Linear{kind:"linear_regression",feature:3,slope,intercept:my-slope*mx} }
struct Rng(u32); impl Rng { fn next(&mut self)->f64 { self.0=self.0.wrapping_mul(1664525).wrapping_add(1013904223); self.0 as f64 / 4294967296.0 } }
fn tree(rows: &[Point], depth: usize, rng: &mut Rng) -> Tree { let value=mean(rows); let leaf=||Tree{value,feature:None,threshold:None,left:None,right:None}; if depth==0 || rows.len()<18 || rows.iter().all(|p|p.y==rows[0].y) {return leaf()} let mut features=Vec::new(); while features.len()<2 {let f=(rng.next()*4.0) as usize; if !features.contains(&f){features.push(f)}} let mut best=None; let mut loss_best=f64::INFINITY; for f in features { let mut vals:Vec<f64>=rows.iter().map(|p|p.x[f]).collect(); vals.sort_by(|a,b|a.total_cmp(b)); vals.dedup(); if vals.len()<2 {continue} let indices:Vec<usize>=if vals.len()<=17 {(0..vals.len()-1).collect()} else {(0..16).map(|i|i*(vals.len()-1)/16).collect()}; for i in indices {let threshold=(vals[i]+vals[i+1])/2.0; let (l,r):(Vec<_>,Vec<_>)=rows.iter().copied().partition(|p|p.x[f]<=threshold); if l.len()<8 || r.len()<8 {continue} let lm=mean(&l);let rm=mean(&r);let loss=l.iter().map(|p|(p.y-lm).powi(2)).sum::<f64>()+r.iter().map(|p|(p.y-rm).powi(2)).sum::<f64>();if loss<loss_best {loss_best=loss;best=Some((f,threshold))}} } if let Some((f,t))=best {let (l,r):(Vec<_>,Vec<_>)=rows.iter().copied().partition(|p|p.x[f]<=t);Tree{value,feature:Some(f),threshold:Some(t),left:Some(Box::new(tree(&l,depth-1,rng))),right:Some(Box::new(tree(&r,depth-1,rng)))}} else {leaf()} }
impl Tree { fn predict(&self,x:&[f64;4])->f64 { match (self.feature,self.threshold,&self.left,&self.right) { (Some(f),Some(t),Some(l),Some(r))=>if x[f]<=t {l.predict(x)} else {r.predict(x)}, _=>self.value } } }
impl Linear { pub fn predict(&self,x:&[f64;4])->f64 {(self.intercept+self.slope*x[self.feature]).max(0.0)} }
impl Forest { pub fn predict(&self,x:&[f64;4])->f64 {(self.trees.iter().map(|t|t.predict(x)).sum::<f64>()/self.trees.len().max(1) as f64).max(0.0)} }
fn score(rows:&[Point],train:usize,predict:impl Fn(&[f64;4])->f64)->Metrics {let m=mean(rows);let mut abs=0.0;let mut sq=0.0;let mut total=0.0;for p in rows {let e=p.y-predict(&p.x);abs+=e.abs();sq+=e*e;total+=(p.y-m).powi(2)} Metrics{mae:abs/rows.len().max(1) as f64,rmse:(sq/rows.len().max(1) as f64).sqrt(),r2:if total==0.0 {0.0}else{1.0-sq/total},train_rows:train,test_rows:rows.len()} }
pub fn train()->Models {let all=dataset();let split=all.len()*8/10;let (training,test)=all.split_at(split);let linear=fit_linear(training);let mut rng=Rng(22112026);let mut trees=Vec::new();for _ in 0..20 {let sample:Vec<_>=(0..training.len()).map(|_|training[(rng.next()*training.len() as f64) as usize]).collect();trees.push(tree(&sample,5,&mut rng));} let forest=Forest{kind:"random_forest",trees,feature_count:4};let linear_metrics=score(test,split,|x|linear.predict(x));let forest_metrics=score(test,split,|x|forest.predict(x));Models{linear,forest,linear_metrics,forest_metrics,test:test.to_vec()} }
#[cfg(test)] mod tests { use super::*; #[test] fn reference_metrics() {let m=train();assert_eq!((m.linear_metrics.train_rows,m.linear_metrics.test_rows),(960,240)); for (v,e) in [(m.linear_metrics.mae,9.9954),(m.linear_metrics.rmse,12.8193),(m.linear_metrics.r2,0.3572),(m.forest_metrics.mae,4.9000),(m.forest_metrics.rmse,6.3266),(m.forest_metrics.r2,0.8434)] {assert!((v-e).abs()<0.001,"{v} != {e}");}} }
